UPDATE fm_api_client_key
   SET EXPIRES_AT = #{expiresAt,jdbcType=TIMESTAMP},
       STATUS = #{status,jdbcType=VARCHAR},
       LOCK_VERSION = LOCK_VERSION + 1,
       UUSERID = #{uuserid,jdbcType=VARCHAR}, UDATE = #{udate,jdbcType=TIMESTAMP}
 WHERE OID = #{oid,jdbcType=CHAR} AND TENANT_ID = #{tenantId,jdbcType=VARCHAR}
   AND LOCK_VERSION = #{lockVersion,jdbcType=INTEGER}

UPDATE fm_api_client_key
   SET STATUS = 'REVOKED', REVOKED_AT = #{revokedAt,jdbcType=TIMESTAMP},
       REVOKED_BY = #{revokedBy,jdbcType=VARCHAR}, REVOKE_REASON = #{revokeReason,jdbcType=VARCHAR},
       LOCK_VERSION = LOCK_VERSION + 1, UUSERID = #{revokedBy,jdbcType=VARCHAR}, UDATE = #{udate,jdbcType=TIMESTAMP}
 WHERE OID = #{oid,jdbcType=CHAR} AND TENANT_ID = #{tenantId,jdbcType=VARCHAR}
   AND STATUS = 'ACTIVE' AND LOCK_VERSION = #{lockVersion,jdbcType=INTEGER}
